import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


_upper_tri_mm_ext = None


def _load_upper_tri_mm_extension():
    global _upper_tri_mm_ext
    if _upper_tri_mm_ext is None:
        cpp_source = r"""
#include <torch/extension.h>

torch::Tensor upper_tri_mm(torch::Tensor A, torch::Tensor B);
"""

        cuda_source = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAGuard.h>
#include <cuda.h>
#include <cuda_runtime.h>

namespace {

constexpr int TILE = 32;
__global__ void upper_triangular_matmul_kernel(
    const float* __restrict__ A,
    const float* __restrict__ B,
    float* __restrict__ C,
    int N
) {
    const int tile_row = blockIdx.y;
    const int tile_col = blockIdx.x;
    if (tile_col < tile_row) {
        return;
    }
    const int tx = threadIdx.x;
    const int ty = threadIdx.y;
    const int row_base = tile_row * TILE + ty * 4;
    const int col_base = tile_col * TILE + tx * 4;
    __shared__ float As[TILE][TILE];
    __shared__ float Bs[TILE][TILE];
    float acc[4][4] = {};
    const int first_k_tile = tile_row;
    const int last_k_tile = tile_col;
    for (int k_tile = first_k_tile; k_tile <= last_k_tile; ++k_tile) {
        const int k_base = k_tile * TILE;
        #pragma unroll
        for (int dy = 0; dy < 4; ++dy) {
            #pragma unroll
            for (int dx = 0; dx < 4; ++dx) {
                const int a_row = row_base + dy;
                const int a_col = k_base + tx * 4 + dx;
                if (a_row < N && a_col < N && a_col >= a_row) {
                    As[ty * 4 + dy][tx * 4 + dx] = A[a_row * N + a_col];
                } else {
                    As[ty * 4 + dy][tx * 4 + dx] = 0.0f;
                }
                const int b_row = k_base + ty * 4 + dy;
                const int b_col = col_base + dx;
                if (b_row < N && b_col < N && b_col >= b_row) {
                    Bs[ty * 4 + dy][tx * 4 + dx] = B[b_row * N + b_col];
                } else {
                    Bs[ty * 4 + dy][tx * 4 + dx] = 0.0f;
                }
            }
        }
        __syncthreads();
        #pragma unroll
        for (int k = 0; k < TILE; ++k) {
            float a[4];
            float b[4];
            #pragma unroll
            for (int i = 0; i < 4; ++i) {
                a[i] = As[ty * 4 + i][k];
            }
            #pragma unroll
            for (int j = 0; j < 4; ++j) {
                b[j] = Bs[k][tx * 4 + j];
            }
            #pragma unroll
            for (int i = 0; i < 4; ++i) {
                #pragma unroll
                for (int j = 0; j < 4; ++j) {
                    acc[i][j] = fmaf(a[i], b[j], acc[i][j]);
                }
            }
        }
        __syncthreads();
    }
    #pragma unroll
    for (int i = 0; i < 4; ++i) {
        #pragma unroll
        for (int j = 0; j < 4; ++j) {
            const int row = row_base + i;
            const int col = col_base + j;
            if (row < N && col < N && row <= col) {
                C[row * N + col] = acc[i][j];
            }
        }
    }
}

} // namespace

torch::Tensor upper_tri_mm(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda(), "A must be a CUDA tensor");
    TORCH_CHECK(B.is_cuda(), "B must be a CUDA tensor");
    TORCH_CHECK(A.scalar_type() == at::kFloat, "A must be float32");
    TORCH_CHECK(B.scalar_type() == at::kFloat, "B must be float32");
    TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "A and B must be 2D tensors");
    TORCH_CHECK(A.size(0) == A.size(1), "A must be square");
    TORCH_CHECK(B.size(0) == B.size(1), "B must be square");
    TORCH_CHECK(A.sizes() == B.sizes(), "A and B must have identical shapes");
    TORCH_CHECK(A.is_contiguous(), "A must be contiguous");
    TORCH_CHECK(B.is_contiguous(), "B must be contiguous");

    const int N = static_cast<int>(A.size(0));
    at::cuda::CUDAGuard device_guard(A.device());

    auto C = torch::zeros({N, N}, A.options());

    if (N == 0) {
        return C;
    }

    const dim3 block(TILE / 4, TILE / 4);
    const dim3 grid((N + TILE - 1) / TILE, (N + TILE - 1) / TILE);

    upper_triangular_matmul_kernel<<<
        grid,
        block,
        0,
        at::cuda::getDefaultCUDAStream()
    >>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        N
    );

    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return C;
